// Corta la cadencia después de las 10:30 (el cron llega hasta 10:59)
const now = $now;
if (now.hour === 10 && now.minute > 30) { return []; }
return [{ json: { ok: true } }];

// Arma el system prompt (calificar+redactar) y el mensaje de usuario con los datos del lead
const lead = $json;
const hoy = $now.toFormat('yyyy-LL-dd');
const system = [
'<identidad>Eres el Agente de Seguimiento Comercial B2B de ACCES GROUP. Venta consultiva (ciberseguridad, SOC 24/7, GRC, cumplimiento, nube, continuidad, PMO, servicios administrados). Partner estrategico, no proveedor de productos. No presionas, no hablas de precio, no inventas datos.</identidad>',
'<objetivo>Calificar un lead ICP y redactar el PRIMER correo de contacto, personalizado con la investigacion de sector provista. Abrir una conversacion breve de bajo riesgo. NO vender en el primer correo.</objetivo>',
'<calificacion>Score_ICP 0-100 = ICP_Fit(0-30)+Intent(0-30)+Viabilidad(0-30)+Engagement(0-10). Umbrales: 0-29 descartar, 30-49 nutrir, 50-64 MQL, 65-74 SAL, 75-100 SQL. Deriva un Micro_ICP.</calificacion>',
'<reglas>Espanol profesional. Estructura: saludo -> hipotesis relevante del sector -> motivo -> reduccion de riesgo -> 1 solo CTA (reunion 20-30 min con 2 fechas) -> cierre sin presion. Max ~130 palabras. Cuerpo en HTML simple (<p>,<br>). Personaliza SIEMPRE con investigacion_sector, etiquetando hipotesis como hipotesis. NO firmes (la firma se agrega aparte). NO afirmes capacidades/casos no provistos. NO uses miedo ni urgencia falsa. Si Score<30 o correo invalido: decision distinta a contactar.</reglas>',
'<salida>Responde SOLO este JSON sin ``` : {"score_icp":<0-100>,"micro_icp":"","decision":"contactar|nutrir|descartar","etapa_pipeline":"Analisis de Requerimiento|Nutricion|Descartado","asunto":"","cuerpo_html":"","razon":"","fecha_siguiente_paso":"YYYY-MM-DD"}</salida>'
].join('\n');
const user = `Fecha de hoy: ${hoy}\nEmpresa: ${lead.Empresa}\nSector: ${lead.Sector}\nContacto: ${lead.Contacto} (${lead.Cargo})\nCorreo: ${lead.Correo}\nCiudad: ${lead.Ciudad || ''}\nInvestigacion de sector/empresa: ${lead.Investigacion_Sector || ''}\n\nCalifica y redacta el primer contacto. Devuelve solo el JSON.`;
return [{ json: { ...lead, system, user, hoy } }];

// Firma corporativa: EDITA aqui o lee de la pestana Config
const FIRMA = '<br><br><table cellpadding="0" cellspacing="0" style="font-family:Arial,sans-serif;font-size:13px;color:#333"><tr><td style="padding-top:12px;border-top:2px solid #0a3d62"><strong style="color:#0a3d62">Nombre Apellido</strong><br><span style="color:#555">Ejecutivo Comercial — ACCES GROUP</span><br><a href="mailto:correo@accesgroup.com" style="color:#0a3d62">correo@accesgroup.com</a> | +52 55 0000 0000<br><a href="https://www.accesgroup.com" style="color:#0a3d62">www.accesgroup.com</a></td></tr></table>';
const resp = $json;
let text = '';
try { text = resp.content[0].text; } catch (e) { text = resp.body ? resp.body.content[0].text : '{}'; }
text = text.replace(/^```json/i,'').replace(/```$/,'').trim();
const data = JSON.parse(text);
const lead = $('Prep Claude').item.json;
data.cuerpo_final = (data.cuerpo_html || '') + FIRMA;
return [{ json: { ...lead, ...data } }];
